-- GERADO por importers/sources/feriados_sudeste.py a partir de data/raw/feriados/regras.json. Licença: Atos oficiais (leis, decretos, decisões e atos de tribunais): domínio público (Lei 9.610/1998 art. 8º IV). Cópias do Querido Diário (Open Knowledge Brasil) e republicação do CNB-SP: citar a fonte. Não edite à mão.
-- Feriados estaduais (RJ, ES) e municipais das capitais e polos do Sudeste. Requer a migration 0202. Só mexe em linhas source = feriados-sudeste.
-- active = false: registrada e nunca aplicada (confiança baixa/unverifiable ou norma inconstitucional); motivo em inactive_reason.
delete from holidays where source = 'feriados-sudeste';
on conflict (day, scope, coalesce(uf, ''), coalesce(ibge_code, '')) do nothing;
